type Props = ComponentProps<typeof TabsView>;
type SecondaryData = Pick<Props['tabs'][number], 'secondaryTabProps' | 'activeSecondaryTabId'>;
// INITIAL_SELECTION_SOURCE_GAP: activePrimaryTab и activeSecondaryTabId инициализируют внутренний state; последующие изменения props source не синхронизирует.
function Example({ tabs, activePrimaryTab, dataTestId, onMainTabChange, onSecondaryTabChange }: {
    tabs: Props['tabs']; activePrimaryTab: NonNullable<Props['activePrimaryTab']>;


    dataTestId: NonNullable<Props['dataTestId']>; onMainTabChange: NonNullable<Props['onMainTabChange']>;
    onSecondaryTabChange: NonNullable<Props['onSecondaryTabChange']>;
}) {
    const validIds = (values: unknown[]) => values.every(id => typeof id === 'string' && id.trim().length > 0) && new Set(values).size === values.length;
    if (!dataTestId.trim()) throw new Error('Нужен dataTestId приложения');
    if (tabs.length !== 3 || !validIds(tabs.map(t=>t.mainTabProps.id))) throw new Error('Нужны реальные tabs с устойчивыми уникальными ID');
    const current = tabs.find(t=>t.mainTabProps.id===activePrimaryTab);
    if (!current) throw new Error('activePrimaryTab должен существовать');
    if (current.secondaryTabProps?.length !== 4 || !validIds(current.secondaryTabProps.map(t=>t.id)) || !current.secondaryTabProps.some(t=>t.id===current.activeSecondaryTabId)) throw new Error('Нужны реальные secondary tabs и выбранный ID');
    const actualTabs = tabs;
    return <TabsView tabs={actualTabs} activePrimaryTab={activePrimaryTab}
        additionalMainTabsWrapperProps={{ showSkeleton: true }}
        additionalSecondaryTabsWrapperProps={{ showSkeleton: true }}
        dataTestId={dataTestId} onMainTabChange={onMainTabChange}
        onSecondaryTabChange={onSecondaryTabChange}
    />;
}

