    ids: { primary: [string, string, string]; secondary: [string, string, string, string]; };
    secondaryByPrimary?: Record<string, SecondaryData>;

    dataTestId: NonNullable<Props['dataTestId']>; onMainTabChange: NonNullable<Props['onMainTabChange']>;
    onSecondaryTabChange: NonNullable<Props['onSecondaryTabChange']>;
}) {
    const validIds = (values: unknown[]) => values.every(id => typeof id === 'string' && id.trim().length > 0) && new Set(values).size === values.length;
    if (!dataTestId.trim()) throw new Error('Нужен dataTestId приложения');
    if (!validIds(ids.primary) || !validIds(ids.secondary)) throw new Error('Нужны уникальные непустые ID вкладок');
    for (const [owner, group] of Object.entries(secondaryByPrimary ?? {})) {
        if (!ids.primary.includes(owner) || owner === ids.primary[0]) throw new Error('Вторичная группа должна принадлежать другой известной primary вкладке');
        if (group.secondaryTabProps?.length && (!validIds(group.secondaryTabProps.map(t=>t.id)) || (group.activeSecondaryTabId !== undefined && !group.secondaryTabProps.some(t=>t.id===group.activeSecondaryTabId)))) throw new Error('Некорректные ID secondary группы');
    }
    const actualTabs: Props['tabs'] = [{

    mainTabProps: { id: ids.primary[0], title: "TabPrimary 1", disabled: false,  },
    secondaryTabProps: [{ id: ids.secondary[0], title: "TabSecondary 1", disabled: false,  },{ id: ids.secondary[1], title: "TabSecondary 2", disabled: false,  },{ id: ids.secondary[2], title: "TabSecondary 3", disabled: false,  },{ id: ids.secondary[3], title: "TabSecondary 4", disabled: false,  },], activeSecondaryTabId: ids.secondary[0],
},{
    ...secondaryByPrimary?.[ids.primary[1]],
    mainTabProps: { id: ids.primary[1], title: "TabPrimary 2", disabled: false,  },

},{
    ...secondaryByPrimary?.[ids.primary[2]],
    mainTabProps: { id: ids.primary[2], title: "TabPrimary 3", disabled: false,  },

},];
    return <TabsView tabs={actualTabs} activePrimaryTab={ids.primary[0]}
        additionalMainTabsWrapperProps={{ showSkeleton: false }}
        additionalSecondaryTabsWrapperProps={{ showSkeleton: false }}
        dataTestId={dataTestId} onMainTabChange={onMainTabChange}
        onSecondaryTabChange={onSecondaryTabChange}
    />;
}

